/**
 * PathFinder - A* pathfinding for NavigationGrid
 *
 * A* pathfinding implementation optimized for NavigationGrid.
 * Uses binary heap priority queue and octile heuristic.
 *
 * Features:
 * - Binary heap priority queue for O(log n) operations
 * - Octile heuristic for 8-connected grids
 * - Path caching with configurable TTL
 * - Node pooling to avoid allocations
 *
 * **Usage**
 *
 * ```js
 * const pathFinder = new PathFinder(navGrid);
 * const path = pathFinder.findPath(startPos, goalPos);
 * if (path) {
 *   // path is array of { x, y, z } waypoints
 * }
 * ```
 *
 * @class PathFinder
 * @short A* pathfinding for NavigationGrid
 * @category Core
 * @tags A*, Search, Pathfinding, Optimization
 */
export class PathFinder {
    /**
     * Create a new pathfinder.
     *
     * @param {NavigationGrid} navGrid - Navigation grid to search.
     * @param {Object} [config] - Configuration options.
     * @param {number} [config.maxIterations=1000] - Maximum A* iterations.
     * @param {number} [config.cacheTimeout=5000] - Path cache TTL in ms.
     */
    constructor(navGrid: NavigationGrid, config?: {
        maxIterations?: number;
        cacheTimeout?: number;
    });
    navGrid: NavigationGrid;
    maxIterations: number;
    cacheTimeout: number;
    _openHeap: BinaryHeap;
    _openSet: Map<any, any>;
    _closedSet: Map<any, any>;
    _nodePool: any[];
    _nodePoolIndex: number;
    _pathCache: Map<any, any>;
    _maxCacheSize: number;
    /**
     * Configure pathfinder parameters.
     *
     * @param {Object} config - Configuration object.
     * @returns {PathFinder} This instance for chaining.
     */
    set(config: any): PathFinder;
    /**
     * Find path from start to goal world positions.
     *
     * @param {THREE.Vector3} start - Start world position.
     * @param {THREE.Vector3} goal - Goal world position.
     * @param {Object} [options] - Search options.
     * @param {number} [options.maxSearchRadius=50] - Max search radius from start.
     * @returns {Array<{x: number, y: number, z: number}>|null} Path waypoints or null.
     */
    findPath(start: THREE.Vector3, goal: THREE.Vector3, options?: {
        maxSearchRadius?: number;
    }): Array<{
        x: number;
        y: number;
        z: number;
    }> | null;
    /**
     * Octile heuristic for 8-connected grid.
     * Better than Manhattan for diagonal movement.
     *
     * @param {Object} cellA - Start cell.
     * @param {Object} cellB - Goal cell.
     * @returns {number} Heuristic distance.
     * @private
     */
    private _heuristic;
    /**
     * Reconstruct path from goal node to start.
     *
     * @param {Object} goalNode - Goal node with parent chain.
     * @returns {Array<{x: number, y: number, z: number}>} Path waypoints.
     * @private
     */
    private _reconstructPath;
    /**
     * Get or create a node from the pool.
     *
     * @param {Object} cell - Cell for the node.
     * @returns {Object} Node object.
     * @private
     */
    private _getNode;
    /**
     * Compute cell key for map lookups.
     * Uses string key to avoid hash collisions.
     *
     * @param {Object} cell - Cell to hash.
     * @returns {string} Cell key.
     * @private
     */
    private _cellHash;
    /**
     * Cache a path result.
     *
     * @param {string} key - Cache key.
     * @param {Array} path - Path to cache.
     * @private
     */
    private _cachePath;
    /**
     * Invalidate all cached paths.
     * Call when navigation grid changes.
     */
    invalidateCache(): void;
    /**
     * Get cache statistics.
     *
     * @returns {Object} Cache info.
     */
    getCacheInfo(): any;
}
import { BinaryHeap } from './BinaryHeap.js';
